SIGNATURE = "stderr|operators/display.py:297|RuntimeError: Operator bpy#ops#object#mode_set#poll() Cannot edit hidden object"


def test_repro():
    mk = core.Monkey()
    mk.run(ACTIONS)
    hits = [f for f in mk.failures if f[1] == SIGNATURE]
    assert not hits, hits[0][2][-1500:]
